// Example: reactive array with objects
const items = ref([
  { id: 1, name: 'Item 1' },
  { id: 2, name: 'Item 2' }
]);

// Example: a function that increments a counter
function nextItem() {
  if (currentIndex.value < items.length - 1) {
    currentIndex.value++;
  } else {
    currentIndex.value = 0;
  }
}

// Example: a function that cycles backward through an array
function prevItem() {
  if (currentIndex.value === 0) {
    currentIndex.value = items.length - 1;
  } else {
    currentIndex.value--;
  }
}

// Displaying an image from an array
const currentImage = images[currentIndex];
<img :src="currentImage.src" :alt="currentImage.alt">
